const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses=['Chưa bắt đầu','Đang làm','Chờ duyệt','Cần chỉnh sửa','Đã duyệt'];
const titles=['Coming Soon','Mở đơn tuyển thành viên','Giới thiệu phân ban','Giới thiệu ban điều hành','Tổng quan dự án · Tầm nhìn & sứ mệnh','Giá trị cốt lõi & thành tựu','Cộng đồng chia sẻ kiến thức','Gia hạn đơn','Giới thiệu cố vấn','Countdown 24h','Đóng đơn','Check mail'];
const dates=['10-28','10-31','11-02','11-05','11-08','11-11','11-13','11-15','11-18','11-22','11-23','11-24'];
// Only supplied campaign posts are initialized. No generated tasks, people, or progress.
function seed(){return {posts:titles.map((title,i)=>({id:'P'+String(i+1).padStart(2,'0'),title,date:'2026-'+dates[i],published:false})),tasks:[],activity:[]};}
const STORAGE_KEY='aiqs-project-v2';
let data;try{data=JSON.parse(localStorage.getItem(STORAGE_KEY))||seed();if(!Array.isArray(data.tasks)||!Array.isArray(data.posts))data=seed();}catch{data=seed();}
// Old prototype storage is deliberately not imported.
let view='dashboard',role='lead',search='',track='',owner='',statusFilter='',answer='',busy=false;
let reportDate=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const phaseNames=['Nền tảng','Tiền kỳ','Chạy chuỗi'];
const phaseDesc=['Storyline · Timeline · Art Direction','Caption nháp · Shotlist · Photoshoot','Caption · Thiết kế · Xuất bản'];
const fmt=d=>d?d.slice(8,10)+'/'+d.slice(5,7):'Chưa có hạn';
const done=t=>t.status==='Đã duyệt';
const blockers=t=>t.deps.map(id=>data.tasks.find(x=>x.id===id)).filter(x=>x&&!done(x));
const overdue=t=>!done(t)&&t.due&&t.due<reportDate;
const stage=t=>t.step||({Photo:'Chuẩn bị / thực hiện', 'Định hướng':'Chốt định hướng'}[t.track]||'');
function badge(s){const cls=s==='Đã duyệt'||s==='Đã đăng'?'green':s==='Chờ duyệt'?'amber':s==='Đang làm'?'blue':s==='Cần chỉnh sửa'||s==='Quá hạn'?'red':'gray';return `<span class="badge ${cls}">${esc(s)}</span>`;}
function metrics(){return {total:data.tasks.length,done:data.tasks.filter(done).length,review:data.tasks.filter(t=>t.status==='Chờ duyệt').length,late:data.tasks.filter(overdue).length,blocked:data.tasks.filter(t=>!done(t)&&blockers(t).length).length};}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000);}
function save(message){data.activity.unshift({text:message,time:new Date().toLocaleString('vi-VN',{timeZone:'Asia/Bangkok'})});data.activity=data.activity.slice(0,15);try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data));toast('Đã lưu trên trình duyệt này');}catch{toast('Không lưu được trên trình duyệt. Hãy xuất bản sao dữ liệu.');}}
function taskRows(tasks){return tasks.map(t=>`<tr data-task="${t.id}" tabindex="0"><td><span class="tasktitle">${esc(t.title)}</span><span class="taskmeta">${t.id} · ${esc(t.owner)}${blockers(t).length?' · Chờ '+blockers(t).map(x=>x.id).join(', '):''}</span></td><td>${badge(t.status)}</td><td style="color:${overdue(t)?'#b56a56':'inherit'}">${fmt(t.due)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Không có công việc phù hợp.</td></tr>';}
function progressPhase(i){const ts=data.tasks.filter(t=>t.phase===i);return ts.length?Math.round(ts.filter(done).length/ts.length*100):0;}
function phaseCards(){return `<div class="phases">${phaseNames.map((name,i)=>`<div class="phase ${''}"><span class="number">GIAI ĐOẠN 0${i+1}</span><h3>${name} <span style="float:right;color:#6e835e">${data.tasks.some(t=>t.phase===i)?progressPhase(i)+'%':'—'}</span></h3><div class="progress"><i style="width:${progressPhase(i)}%"></i></div><p>${phaseDesc[i]}</p></div>`).join('')}</div>`;}
function aiPanel(){const m=metrics();const first=data.tasks.find(t=>t.status==='Chờ duyệt');return `<section class="panel insights"><div class="panelhead"><div class="aihead"><span class="spark">✧</span><div><h2>Nắm nhanh chiến dịch</h2><p>Tổng hợp tự động từ bảng công việc</p></div></div></div><div class="brief"><p><b>${m.total?m.done+'/'+m.total+' đầu việc đã duyệt.':'Chưa có công việc được nhập; chưa thể đánh giá tiến độ.'}</b> ${m.review?`Có ${m.review} việc chờ quyết định của Trưởng ban.`:'Không có việc chờ duyệt.'}</p><div class="insightitem"><i class="dot"></i><span><b>${m.late} việc quá hạn</b><br>So với ngày ${fmt(reportDate)}. Ưu tiên kiểm tra deadline trước.</span></div><div class="insightitem"><i class="dot"></i><span><b>${m.blocked} việc đang chờ đầu vào</b><br>Ảnh cần chốt trước khi duyệt cuối caption và thiết kế.</span></div><div class="insightitem"><i class="dot"></i><span><b>Ưu tiên tiếp theo</b><br>${first?'Duyệt '+esc(first.title)+' ('+first.id+').':(m.total?'Kiểm tra các việc đang làm và phân công còn thiếu.':'Thêm các công việc đã thống nhất trong tab Workflow.')}</span></div><div style="border-top:1px solid #dce5d3;padding-top:17px;margin-top:6px"><h3>Hỏi trợ lý AI <span class="badge gray">Model qua API</span></h3><p class="muted" style="font-size:10px">AI phân tích dữ liệu đang xem. Cần cấu hình model để sử dụng.</p><button class="question" id="quickask">Điều gì có thể làm trễ lịch đăng?</button><form id="aiform"><div class="aiinput"><input id="question" aria-label="Câu hỏi cho AI" placeholder="Hỏi về chiến dịch…" maxlength="1500" required><button class="primary" ${busy?'disabled':''} aria-label="Gửi câu hỏi">${busy?'…':'↑'}</button></div></form><button id="aitoken" class="mini" style="margin-top:9px">Mã truy cập AI</button><div class="answer" role="status">${esc(answer)}</div></div></div></section>`;}
function dashboard(){const m=metrics();const priorities=[...data.tasks].filter(t=>!done(t)).sort((a,b)=>Number(overdue(b))-Number(overdue(a))||Number(b.status==='Chờ duyệt')-Number(a.status==='Chờ duyệt')||a.due.localeCompare(b.due)).slice(0,5);return `<div class="stats">${[[data.posts.length,'BÀI ĐĂNG TRONG CHUỖI','28/10 — 24/11/2026','▤'],[m.total?Math.round(m.done/m.total*100)+'%':'—','TIẾN ĐỘ CÔNG VIỆC',m.done+' / '+m.total+' đầu việc đã duyệt','◉'],[m.review,'ĐANG CHỜ DUYỆT','Cần Trưởng ban phản hồi','◷'],[m.late,'CÔNG VIỆC QUÁ HẠN','Tính theo ngày đang xem','↗']].map(([v,l,h,i])=>`<div class="stat"><label>${l}</label><span class="icon">${i}</span><strong>${v}</strong><small>${h}</small></div>`).join('')}</div><div class="two"><div><section class="panel"><div class="panelhead"><div><h2>Hành trình chiến dịch</h2><p>Ba giai đoạn, một luồng phối hợp</p></div><button class="mini" data-view="phases">Chi tiết ↗</button></div>${phaseCards()}</section><section class="panel"><div class="panelhead"><div><h2>Cần bạn chú ý</h2><p>Ưu tiên việc quá hạn và đang chờ duyệt</p></div><button class="mini" data-view="workflow">Tất cả công việc →</button></div><div class="tablewrap"><table><thead><tr><th>CÔNG VIỆC / NGƯỜI PHỤ TRÁCH</th><th>TRẠNG THÁI</th><th>HẠN</th></tr></thead><tbody>${taskRows(priorities)}</tbody></table></div></section><section class="panel"><div class="panelhead"><div><h2>Lịch đăng sắp tới</h2><p>Theo kế hoạch tuyển thành viên của AIQS Project</p></div><button class="mini" data-view="timeline">Xem lịch →</button></div><div class="sectionbody">${data.posts.filter(p=>p.date>=reportDate).slice(0,3).map(p=>`<div class="event"><span class="avatar">${p.date.slice(-2)}</span><div><p>${esc(p.title)}</p><small>${fmt(p.date)} · ${readiness(p)}</small></div></div>`).join('')||'<p class="muted">Không còn bài trong khoảng ngày này.</p>'}</div></section></div><aside>${aiPanel()}<section class="panel"><div class="panelhead"><h2>Cập nhật gần đây</h2></div><div class="activity">${data.activity.length?data.activity.slice(0,3).map(a=>`<div class="event"><span class="avatar">TB</span><div><p>${esc(a.text)}</p><small>${esc(a.time)}</small></div></div>`).join(''):'<div class="event"><span class="avatar">✦</span><div><p>Chưa có cập nhật</p><small>Chỉ ghi nhận các thay đổi bạn thực hiện.</small></div></div>'}</div></section></aside></div>`;}
function readiness(p){if(p.published)return 'Đã đăng';const tasks=data.tasks.filter(t=>t.post===p.id);if(!tasks.length)return 'Chưa có dữ liệu tiến độ';return tasks.every(done)?'Sẵn sàng đăng':`${tasks.filter(done).length}/${tasks.length} đầu việc đã duyệt`;}
function filtered(){return data.tasks.filter(t=>(!track||t.track===track)&&(!owner||t.owner===owner)&&(!statusFilter||t.status===statusFilter)&&(!search||(t.title+' '+t.id+' '+t.owner).toLowerCase().includes(search.toLowerCase())));}
function filters(){return `<div class="toolbar"><input id="search" placeholder="Tìm công việc, mã bài, người phụ trách…" value="${esc(search)}" aria-label="Tìm công việc"><select id="track" aria-label="Lọc tuyến"><option value="">Tất cả tuyến</option>${['Định hướng','Nội dung','Photo','Thiết kế','Motion & Animation'].map(x=>`<option ${track===x?'selected':''}>${x}</option>`).join('')}</select><select id="owner" aria-label="Lọc người phụ trách"><option value="">Tất cả thành viên</option>${[...new Set(data.tasks.map(t=>t.owner))].map(x=>`<option ${owner===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="statusFilter" aria-label="Lọc trạng thái"><option value="">Mọi trạng thái</option>${statuses.map(x=>`<option ${statusFilter===x?'selected':''}>${x}</option>`).join('')}</select></div>`;}
function workflow(){const ts=filtered();return (role==='lead'?'<button class="primary" id="addtask" style="margin-bottom:16px">+ Thêm công việc</button>':'')+filters()+`<div class="kanban">${[['Chưa bắt đầu'],['Đang làm','Cần chỉnh sửa'],['Chờ duyệt'],['Đã duyệt']].map((group,i)=>{const items=ts.filter(t=>group.includes(t.status));return `<section class="lane"><div class="lanehead"><b>${['Chưa bắt đầu','Đang thực hiện','Chờ duyệt','Đã duyệt'][i]}</b><span>${items.length}</span></div>${items.map(t=>`<button class="card" data-task="${t.id}"><span class="badge ${t.track==='Nội dung'?'blue':t.track==='Photo'?'amber':'green'}">${t.track}</span><h3>${esc(t.title)}</h3>${t.status==='Cần chỉnh sửa'?badge(t.status):''}${blockers(t).length?'<span class="badge gray">Chờ đầu vào</span>':''}<span class="taskmeta">${t.id} · ${esc(stage(t))}</span><footer><span>${esc(t.owner.replace('Thành viên ',''))}</span><span style="color:${overdue(t)?'#b56a56':'inherit'}">${fmt(t.due)}</span></footer></button>`).join('')||'<div class="empty">Chưa có công việc</div>'}</section>`;}).join('')}</div>`;}
function timeline(){return `<section class="panel"><div class="panelhead"><div><h2>12 điểm chạm của Arecibo</h2><p>Trạng thái sẵn sàng được tổng hợp từ caption và thiết kế</p></div></div><div class="tablewrap"><table><thead><tr><th>NGÀY ĐĂNG</th><th>BÀI ĐĂNG</th><th>CAPTION</th><th>THIẾT KẾ</th><th>XUẤT BẢN</th></tr></thead><tbody>${data.posts.map(p=>`<tr data-post="${p.id}" tabindex="0"><td>${fmt(p.date)}</td><td><span class="tasktitle">${esc(p.title)}</span><span class="taskmeta">${p.id}</span></td><td>${badge(data.tasks.find(t=>t.post===p.id&&t.track==='Nội dung')?.status||'Chưa có công việc')}</td><td>${badge(data.tasks.find(t=>t.post===p.id&&t.track==='Thiết kế')?.status||'Chưa có công việc')}</td><td>${badge(readiness(p))}</td></tr>`).join('')}</tbody></table></div></section>`;}
function members(){return `<div class="membergrid">${[...new Set(data.tasks.map(t=>t.owner))].map((name,i)=>{const ts=data.tasks.filter(t=>t.owner===name);return `<section class="membercard"><span class="avatar">${i?'0'+i:'TB'}</span><h3>${esc(name)}</h3><p>${ts.length} đầu việc · ${ts.filter(done).length} đã duyệt · ${ts.filter(overdue).length} quá hạn</p><div class="progress"><i style="width:${Math.round(ts.filter(done).length/ts.length*100)}%"></i></div><button class="mini" data-member="${esc(name)}" style="margin-top:20px">Xem công việc →</button></section>`;}).join('')}</div><p class="notice">Danh sách chỉ xuất hiện khi bạn phân công công việc cho người phụ trách.</p>`;}
function phases(){return `<section class="panel"><div class="panelhead"><h2>Quy trình tham chiếu · AIQS Project</h2></div><div class="sectionbody"><p><b>Nội dung:</b> First Draft D−4 → Feedback / chỉnh sửa → Final D−2 → Đăng & seeding D-day.</p><p><b>Hình ảnh:</b> Design phụ trách wireframe; Photo phụ trách shotlist; Content cùng góp ý. Lịch chụp, gear, địa điểm, đạo cụ và IC Assist được chuẩn bị trước buổi chụp.</p><p><b>Sau photoshoot:</b> tài liệu nêu hậu kỳ ảnh D−6 và thiết kế Final D−2. Chiến dịch gấp cần điều chỉnh deadline trước buổi chụp; không tự áp lịch cứng.</p><p><b>Phân vai:</b> Trưởng ban cập nhật tiến độ; thành viên theo dõi. IC thực hiện, người duyệt và người điều phối toàn chiến dịch là các trách nhiệm riêng.</p><p class="notice">Hướng dẫn tham chiếu, không phải công việc đã được giao. Không tự sinh task, gán người hoặc suy đoán tiến độ.</p></div></section>`+phaseNames.map((name,i)=>`<section class="panel phasebig"><span class="eyebrow">GIAI ĐOẠN 0${i+1}</span><h2 style="margin-top:10px">${name}</h2><p class="muted">${phaseDesc[i]}</p><div class="progress"><i style="width:${progressPhase(i)}%"></i></div><p>${data.tasks.some(t=>t.phase===i)?progressPhase(i)+'% công việc đã duyệt':'Chưa có công việc được nhập'}</p><div class="milestones">${data.tasks.filter(t=>t.phase===i).map(t=>`<button data-task="${t.id}">${esc(t.title)} · ${esc(t.status)}</button>`).join('')}</div></section>`).join('');}
function render(){const labels={dashboard:'Tổng quan chiến dịch',phases:'Giai đoạn chiến dịch',workflow:'Workflow công việc',timeline:'Lịch đăng nội dung',members:'Theo dõi thành viên'};$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="logo">a</span>AIQS<span style="color:#7d9869;font-weight:400">Project</span></div><div class="subbrand">CAMPAIGN WORKSPACE</div><div class="navlabel">KHÔNG GIAN LÀM VIỆC</div><nav>${[['dashboard','◫','Dashboard'],['phases','◇','Giai đoạn'],['workflow','▥','Workflow'],['timeline','▦','Lịch đăng'],['members','♧','Thành viên']].map(([id,icon,title])=>`<button class="nav ${view===id?'active':''}" data-view="${id}"><span>${icon}</span>${title}</button>`).join('')}</nav><div class="sidefoot"><span class="badge green">● Chiến dịch Arecibo</span><p><strong>AIQS · Tuyển thành viên</strong><br>28.10 — 24.11.2026</p><button id="export" class="mini">Xuất dữ liệu ↓</button></div></aside><main class="main"><header class="topbar"><div class="crumb">AIQS Project <b>/ Chiến dịch Arecibo</b></div><div class="topright"><span class="badge amber">Lưu cục bộ</span><select id="role" aria-label="Chế độ xem"><option value="lead" ${role==='lead'?'selected':''}>Trưởng ban · cập nhật</option><option value="member" ${role==='member'?'selected':''}>Thành viên · theo dõi</option></select><span class="avatar">${role==='lead'?'TB':'TV'}</span></div></header><div class="page"><div class="intro"><div><span class="eyebrow">AIQS PROJECT / ARECIBO 2026</span><h1>${labels[view]}</h1><p class="muted">${role==='lead'?'Một góc nhìn chung. Phối hợp nhịp nhàng hơn.':'Theo dõi công việc, phản hồi và các mốc cần hoàn thành.'}</p></div><label style="font-size:10px;color:#87917f">Ngày đối chiếu<br><input id="reportDate" type="date" value="${reportDate}" aria-label="Ngày đối chiếu" style="margin-top:6px;max-width:145px"></label></div>${({dashboard,workflow,timeline,members,phases}[view])()}<p class="notice">Lịch bài từ kế hoạch bạn cung cấp. Công việc và phân công do Trưởng ban nhập; không tự sinh. Dữ liệu lưu trên trình duyệt này, chưa đồng bộ Google Sheets. Chế độ xem chưa phải phân quyền tài khoản.</p></div></main></div>`;
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});
 document.querySelectorAll('[data-task]').forEach(b=>{b.onclick=()=>detail(b.dataset.task);b.onkeydown=e=>{if(e.key==='Enter')detail(b.dataset.task);};});
 document.querySelectorAll('[data-post]').forEach(b=>{b.onclick=()=>postDetail(b.dataset.post);b.onkeydown=e=>{if(e.key==='Enter')postDetail(b.dataset.post);};});
 document.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>{owner=b.dataset.member;view='workflow';render();});
 if($('#addtask'))$('#addtask').onclick=addTask;
 $('#role').onchange=e=>{role=e.target.value;render();};$('#reportDate').onchange=e=>{if(e.target.value){reportDate=e.target.value;render();}};
 for(const id of ['track','owner','statusFilter'])if($('#'+id))$('#'+id).onchange=e=>{if(id==='track')track=e.target.value;if(id==='owner')owner=e.target.value;if(id==='statusFilter')statusFilter=e.target.value;render();};
 if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};
 $('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='aiqs-project.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 if($('#aiform'))$('#aiform').onsubmit=e=>{e.preventDefault();ask($('#question').value);};if($('#quickask'))$('#quickask').onclick=()=>ask('Điều gì có thể làm trễ lịch đăng? Nêu các mã công việc và 3 ưu tiên tiếp theo.');
 if($('#aitoken'))$('#aitoken').onclick=()=>{const d=$('#detail');d.innerHTML='<button class="close" id="close">×</button><h2>Mã truy cập AI</h2><p class="muted">Nhập mã APP_ACCESS_TOKEN của bản triển khai. Mã chỉ giữ trong bộ nhớ đến khi tải lại trang.</p><form id="tokenform"><input type="password" id="token" aria-label="Mã truy cập" required autocomplete="off" style="width:100%"><div class="dialogactions"><button class="primary">Sử dụng mã</button></div></form>';$('#close').onclick=()=>d.close();$('#tokenform').onsubmit=e=>{e.preventDefault();accessToken=$('#token').value;d.close();toast('Đã đặt mã truy cập cho phiên này');};d.showModal();};
}
function detail(id){const t=data.tasks.find(x=>x.id===id);const d=$('#detail');const locked=role!=='lead';const steps=t.track==='Nội dung'?['Viết Caption','1st Draft','Feedback','Chốt theo hình ảnh']:t.track==='Thiết kế'?['Sketch Layout','Thiết Kế','1st Draft','Feedback','Chốt']:['Chuẩn bị','Thực hiện','Feedback','Chốt'];d.innerHTML=`<button class="close" id="close" aria-label="Đóng">×</button><span class="eyebrow">${t.id} / ${phaseNames[t.phase]}</span><h2 style="margin-top:14px;line-height:1.7">${esc(t.title)}</h2>${badge(t.status)}<form id="edit"><div class="formgrid"><div class="field"><label>IC thực hiện</label><input name="owner" value="${esc(t.owner)}" ${locked?'disabled':''} required maxlength="100"></div><div class="field"><label>Người duyệt</label><input name="reviewer" value="${esc(t.reviewer)}" ${locked?'disabled':''} required maxlength="100"></div><div class="field"><label>Deadline</label><input name="due" type="date" value="${t.due}" ${locked?'disabled':''} required></div><div class="field"><label>Trạng thái</label><select name="status" ${locked?'disabled':''}>${statuses.map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="field wide"><label>Bước triển khai</label><select name="step" ${locked?'disabled':''}>${[...new Set([t.step||steps[0],...steps])].map(s=>`<option ${s===t.step?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="field wide"><label>Feedback / yêu cầu chỉnh sửa</label><textarea name="feedback" ${locked?'disabled':''} maxlength="3000">${esc(t.feedback||'')}</textarea></div><div class="field wide"><label>Link sản phẩm</label><input name="link" type="url" placeholder="https://…" value="${esc(t.link||'')}" ${locked?'disabled':''}></div></div><div class="dependency"><b>Đầu vào cần chốt:</b> ${t.deps.length?t.deps.map(id=>{const dep=data.tasks.find(x=>x.id===id);return esc(dep.title)+' ('+esc(dep.status)+')';}).join('; '):'Không có phụ thuộc.'}<br><span class="muted">${t.updated?'Cập nhật gần nhất: '+esc(t.updated):'Chưa cập nhật trong phiên thử.'}</span></div>${t.link&&/^https?:\/\//.test(t.link)?`<p><a href="${esc(t.link)}" target="_blank" rel="noopener">Mở sản phẩm ↗</a></p>`:''}<p id="editerror" style="color:#b56a56" role="alert"></p><div class="dialogactions">${locked?'<span class="muted">Chế độ thành viên · chỉ xem</span>':'<button class="primary">Lưu cập nhật</button>'}</div></form>`;$('#close').onclick=()=>d.close();$('#edit').onsubmit=e=>{e.preventDefault();if(locked)return;const f=new FormData(e.target);if(f.get('status')==='Đã duyệt'&&blockers(t).length){$('#editerror').textContent='Cần chốt các đầu vào phụ thuộc trước khi duyệt cuối.';return;}if(!f.get('owner').trim()||!f.get('reviewer').trim()){ $('#editerror').textContent='Vui lòng nhập người phụ trách và người duyệt.';return;}const wasDone=done(t);for(const k of ['owner','reviewer','due','status','step','feedback','link'])t[k]=f.get(k);t.updated=new Date().toLocaleString('vi-VN',{timeZone:'Asia/Bangkok'});if(wasDone&&!done(t))data.tasks.filter(x=>x.deps.includes(t.id)&&done(x)).forEach(x=>{x.status='Cần chỉnh sửa';x.feedback=(x.feedback||'')+'\nCần kiểm tra lại do đầu vào '+t.id+' thay đổi.';});save(t.id+' · '+t.status);d.close();render();};d.showModal();}
function postDetail(id){const p=data.posts.find(x=>x.id===id);const ts=data.tasks.filter(t=>t.post===id);const d=$('#detail');d.innerHTML=`<button class="close" id="close">×</button><span class="eyebrow">${id} · ${fmt(p.date)}</span><h2 style="margin-top:12px">${esc(p.title)}</h2><p>${readiness(p)}</p><div class="postflow">${ts.map(t=>`<button data-open="${t.id}">${t.track} · ${t.status}</button>`).join('')}</div>${role==='lead'?`<div class="dialogactions"><button id="publish" class="primary" ${!p.published&&(!ts.length||!ts.every(done))?'disabled':''}>${p.published?'Bỏ đánh dấu đã đăng':'Đánh dấu đã đăng'}</button></div>`:''}<p class="notice">Chỉ ghi nhận trạng thái; không tự đăng lên mạng xã hội.</p>`;$('#close').onclick=()=>d.close();d.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{d.close();detail(b.dataset.open);});if($('#publish'))$('#publish').onclick=()=>{p.published=!p.published;save(id+(p.published?' · Đã đăng':' · Chưa đăng'));d.close();render();};d.showModal();}
function addTask(){
 if(role!=='lead')return;
 const d=$('#detail');d.innerHTML=`<button class="close" id="close" aria-label="Đóng">×</button><h2>Thêm công việc</h2><p class="muted">Nhập đầu việc đã thống nhất. Deadline, IC và người duyệt không tự điền.</p><form id="newtask"><div class="formgrid"><div class="field wide"><label>Tên công việc</label><input name="title" required maxlength="200"></div><div class="field"><label>Giai đoạn</label><select name="phase">${phaseNames.map((n,i)=>`<option value="${i}">${n}</option>`).join('')}</select></div><div class="field"><label>Tuyến</label><select name="track">${['Định hướng','Nội dung','Photo','Thiết kế','Motion & Animation'].map(n=>`<option>${n}</option>`).join('')}</select></div><div class="field wide"><label>Bài đăng liên quan (tùy chọn)</label><select name="post"><option value="">Công việc chung</option>${data.posts.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></div><div class="field"><label>IC thực hiện (tùy chọn)</label><input name="owner" maxlength="100"></div><div class="field"><label>Người duyệt (tùy chọn)</label><input name="reviewer" maxlength="100"></div><div class="field"><label>Deadline (tùy chọn)</label><input name="due" type="date"></div></div><div class="dialogactions"><button class="primary">Tạo công việc</button></div></form>`;
 $('#close').onclick=()=>d.close();$('#newtask').onsubmit=e=>{e.preventDefault();if(role!=='lead')return;const f=new FormData(e.target);const title=f.get('title').trim();if(!title)return;const task={id:'T-'+crypto.randomUUID().slice(0,8),title,phase:Number(f.get('phase')),track:f.get('track'),post:f.get('post')||undefined,owner:f.get('owner').trim()||'Chưa phân công',reviewer:f.get('reviewer').trim()||'Chưa chỉ định',due:f.get('due'),status:'Chưa bắt đầu',deps:[]};data.tasks.push(task);save('Tạo '+task.id+' · '+title);d.close();render();};d.showModal();
}
let accessToken='';
async function ask(question){if(busy||!question.trim())return;busy=true;answer='Đang yêu cầu AI phân tích…';render();try{const snapshot={organization:'AIQS Project',campaign:'Arecibo · Tuyển thành viên đợt 2',dataType:'Lịch bài do người dùng cung cấp; tiến độ chỉ gồm các công việc người dùng tự nhập. Không có công việc không đồng nghĩa đã hoàn thành.',asOf:reportDate,metrics:metrics(),posts:data.posts,tasks:data.tasks.map(({id,title,owner,reviewer,due,status,track,phase,deps})=>({id,title,owner,reviewer,due,status,track,phase:phaseNames[phase],deps}))};const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+accessToken},body:JSON.stringify({question,snapshot})});const result=await r.json();answer=r.ok?result.answer:result.error||'Không thể nhận phản hồi.';}catch{answer='Không kết nối được API. Hãy chạy bản web qua server hoặc Vercel.';}finally{busy=false;render();}}
render();
